{
  "candidates": [
    {
      "diagnosis": "Handles clone_place, move_existing, resize_existing with observe-and-correct pattern using the worked example's correction strategy.",
      "program": [
        {
          "op": "for_each",
          "var": "t",
          "over": { "ref": "inputs.targets" },
          "body": [
            {
              "op": "if",
              "cond": { "op": "eq", "args": [{ "ref": "locals.t.kind" }, "clone_place"] },
              "then": [
                { "op": "call", "tool": "clone_node", "args": { "node_id": { "ref": "locals.t.proto" }, "new_id": { "ref": "locals.t.symbol" } } },
                { "op": "call", "tool": "move_node", "args": { "node_id": { "ref": "locals.t.symbol" }, "x": { "ref": "locals.t.x" }, "y": { "ref": "locals.t.y" } } },
                { "op": "call", "tool": "observe_geometry", "args": { "node_ids": { "op": "list", "args": [{ "ref": "locals.t.symbol" }] } }, "bind": "obs_move" },
                { "op": "let", "name": "left", "value": { "ref": "locals.obs_move.bounds.0.left" } },
                { "op": "let", "name": "top", "value": { "ref": "locals.obs_move.bounds.0.top" } },
                {
                  "op": "if",
                  "cond": { "op": "or", "args": [{ "op": "ne", "args": [{ "ref": "locals.left" }, { "ref": "locals.t.x" }] }, { "op": "ne", "args": [{ "ref": "locals.top" }, { "ref": "locals.t.y" }] }] },
                  "then": [
                    { "op": "call", "tool": "move_node", "args": { "node_id": { "ref": "locals.t.symbol" }, "x": { "op": "add", "args": [{ "ref": "locals.t.x" }, { "op": "sub", "args": [{ "ref": "locals.t.x" }, { "ref": "locals.left" }] }] }, "y": { "op": "add", "args": [{ "ref": "locals.t.y" }, { "op": "sub", "args": [{ "ref": "locals.t.y" }, { "ref": "locals.top" }] }] } } }
                  ],
                  "else": []
                },
                { "op": "call", "tool": "resize_node", "args": { "node_id": { "ref": "locals.t.symbol" }, "width": { "ref": "locals.t.w" }, "height": { "ref": "locals.t.h" } } },
                { "op": "call", "tool": "observe_geometry", "args": { "node_ids": { "op": "list", "args": [{ "ref": "locals.t.symbol" }] } }, "bind": "obs_resize" },
                { "op": "let", "name": "width", "value": { "ref": "locals.obs_resize.bounds.0.width" } },
                { "op": "let", "name": "height", "value": { "ref": "locals.obs_resize.bounds.0.height" } },
                {
                  "op": "if",
                  "cond": { "op": "or", "args": [{ "op": "ne", "args": [{ "ref": "locals.width" }, { "ref": "locals.t.w" }] }, { "op": "ne", "args": [{ "ref": "locals.height" }, { "ref": "locals.t.h" }] }] },
                  "then": [
                    { "op": "call", "tool": "resize_node", "args": { "node_id": { "ref": "locals.t.symbol" }, "width": { "op": "add", "args": [{ "ref": "locals.t.w" }, { "op": "sub", "args": [{ "ref": "locals.t.w" }, { "ref": "locals.width" }] }] }, "height": { "op": "add", "args": [{ "ref": "locals.t.h" }, { "op": "sub", "args": [{ "ref": "locals.t.h" }, { "ref": "locals.height" }] }] } } }
                  ],
                  "else": []
                }
              ],
              "else": [
                {
                  "op": "if",
                  "cond": { "op": "eq", "args": [{ "ref": "locals.t.kind" }, "move_existing"] },
                  "then": [
                    { "op": "call", "tool": "move_node", "args": { "node_id": { "ref": "locals.t.id" }, "x": { "ref": "locals.t.x" }, "y": { "ref": "locals.t.y" } } },
                    { "op": "call", "tool": "observe_geometry", "args": { "node_ids": { "op": "list", "args": [{ "ref": "locals.t.id" }] } }, "bind": "obs_move" },
                    { "op": "let", "name": "left", "value": { "ref": "locals.obs_move.bounds.0.left" } },
                    { "op": "let", "name": "top", "value": { "ref": "locals.obs_move.bounds.0.top" } },
                    {
                      "op": "if",
                      "cond": { "op": "or", "args": [{ "op": "ne", "args": [{ "ref": "locals.left" }, { "ref": "locals.t.x" }] }, { "op": "ne", "args": [{ "ref": "locals.top" }, { "ref": "locals.t.y" }] }] },
                      "then": [
                        { "op": "call", "tool": "move_node", "args": { "node_id": { "ref": "locals.t.id" }, "x": { "op": "add", "args": [{ "ref": "locals.t.x" }, { "op": "sub", "args": [{ "ref": "locals.t.x" }, { "ref": "locals.left" }] }] }, "y": { "op": "add", "args": [{ "ref": "locals.t.y" }, { "op": "sub", "args": [{ "ref": "locals.t.y" }, { "ref": "locals.top" }] }] } } }
                      ],
                      "else": []
                    }
                  ],
                  "else": [
                    {
                      "op": "if",
                      "cond": { "op": "eq", "args": [{ "ref": "locals.t.kind" }, "resize_existing"] },
                      "then": [
                        { "op": "call", "tool": "resize_node", "args": { "node_id": { "ref": "locals.t.id" }, "width": { "ref": "locals.t.w" }, "height": { "ref": "locals.t.h" } } },
                        { "op": "call", "tool": "observe_geometry", "args": { "node_ids": { "op": "list", "args": [{ "ref": "locals.t.id" }] } }, "bind": "obs_resize" },
                        { "op": "let", "name": "width", "value": { "ref": "locals.obs_resize.bounds.0.width" } },
                        { "op": "let", "name": "height", "value": { "ref": "locals.obs_resize.bounds.0.height" } },
                        {
                          "op": "if",
                          "cond": { "op": "or", "args": [{ "op": "ne", "args": [{ "ref": "locals.width" }, { "ref": "locals.t.w" }] }, { "op": "ne", "args": [{ "ref": "locals.height" }, { "ref": "locals.t.h" }] }] },
                          "then": [
                            { "op": "call", "tool": "resize_node", "args": { "node_id": { "ref": "locals.t.id" }, "width": { "op": "add", "args": [{ "ref": "locals.t.w" }, { "op": "sub", "args": [{ "ref": "locals.t.w" }, { "ref": "locals.width" }] }] }, "height": { "op": "add", "args": [{ "ref": "locals.t.h" }, { "op": "sub", "args": [{ "ref": "locals.t.h" }, { "ref": "locals.height" }] }] } } }
                          ],
                          "else": []
                        }
                      ],
                      "else": []
                    }
                  ]
                }
              ]
            }
          ]
        }
      ]
    }
  ]
}
